def main():
    assert len(SPECS) == 88, len(SPECS)
    nouns = [s["noun"] for s in SPECS]
    prefixes = [s["prefix"] for s in SPECS]
    slugs = [s["ok_slug"] for s in SPECS] + [s["bad_slug"] for s in SPECS]
    assert len(set(nouns)) == 88, [n for n in nouns if nouns.count(n) > 1]
    assert len(set(prefixes)) == 88, [p for p in prefixes if prefixes.count(p) > 1]
    assert len(set(slugs)) == 176, [s for s in slugs if slugs.count(s) > 1]
    header = '''"""Observability leftover9 plants r964+.

BAN r963 tecton-workspace-remap / leftover8 dock-apron, r875 tempo-ingester-max-traces-per-user-one,
r384 otel-forward-connector, PagerDuty orch, Opsgenie alias, Rootly urgency,
and r163-r963 tempo/rootly/otel clones plus leftover8 CDN/WAF/gateway plants.
Leftover9 lie: silent remap, wrong dashboard, dropped label, filter drop.
"""

from mill_plants_t import _leftover_pair

MORE = []
ROUND_PAIRS = {}


def _emit(round_n, **kwargs):
    dest = []
    _leftover_pair(n=str(round_n), dest=dest, **kwargs)
    MORE.extend(dest)
    ROUND_PAIRS[round_n] = dest[0]


def _l9(n, **kw):
    vendor, noun, prefix = kw["vendor"], kw["noun"], kw["prefix"]
    ok_svc, bad_svc = f"quay-{noun}-svc", f"wharf-{noun}-svc"
    tag = noun.replace("-", "")[:8]
    vtag = prefix.replace("-", "")[:5]
    ok_dash, bad_dash = f"{tag}-{vtag}-{n}", f"q{tag[:7]}-{vtag}-fl"
    lie_core = kw["lie_core"]
    _emit(
        n,
        kind="grafana",
        ok_slug=kw["ok_slug"],
        bad_slug=kw["bad_slug"],
        ok_svc=ok_svc,
        bad_svc=bad_svc,
        ok_dash=ok_dash,
        bad_dash=bad_dash,
        panel=kw["panel"],
        metric="",
        needle=kw["needle"],
        lie=(
            f"{vendor} leftover leftover leftover leftover leftover leftover leftover leftover leftover {lie_core} "
            f"so Grafana dashboard {ok_dash} is empty while the source still 202"
        ),
        bad_lie=(
            f"{kw['false_lead']} does not restore leftover leftover leftover leftover leftover leftover leftover leftover leftover {lie_core}"
        ),
        false_lead=kw["false_lead"],
        avoided=kw["avoided"],
        this_is=f"{vendor} leftover leftover leftover leftover leftover leftover leftover leftover leftover {lie_core}",
        ticket=f"OBS-{8300 + (n - 964)}",
        knob=kw["knob"],
        old=kw["old"],
        new=kw["new"],
        wrong_knob=kw["wrong_knob"],
        wrong_old=kw["wrong_old"],
        wrong_new=kw["wrong_new"],
        wrong2_old=kw["wrong2_old"],
        wrong2_new=kw["wrong2_new"],
        reload="grafana",
        config_path=f"{prefix}/{tag}-false.yaml",
        lie_path=f"{prefix}/{tag}-lie.yaml",
        bad_config=f"{prefix}/q{tag[:7]}-false.yaml",
        bad_lie_path=f"{prefix}/q{tag[:7]}-lie.yaml",
    )


BAN = (
    "r963 tecton-workspace-remap-leftover; r875 tempo-ingester-max-traces-per-user-one; "
    "r384 otel-forward-connector; PagerDuty orch; Opsgenie alias; r515 Rootly urgency; "
    "leftover8 dock/apron r876-r963"
)

SPECS = [
'''
    lines = [header]
    for spec in SPECS:
        avoided = BAN_PLACEHOLDER if False else spec["avoided"]
        # BAN is concatenated at runtime
        d = dict(spec)
        d["avoided"] = "BAN" + spec["avoided"]
        # write as dict(...) with avoided=BAN+...
        items = []
        for k, v in spec.items():
            if k == "avoided":
                items.append(f'avoided=BAN{v!r}.replace("","") and BAN+{v!r}' if False else None)
        # simpler: avoided=BAN+"; ..."
        parts = []
        for k, v in spec.items():
            if k == "avoided":
                parts.append(f"avoided=BAN{v!r}" if v.startswith(";") else f"avoided=BAN+{v!r}")
                # v already starts with "; "
                parts[-1] = f"avoided=BAN{v!r}"
                # BAN + "; leftover8..."  => avoided=BAN+"; leftover8..."
                parts[-1] = f"avoided=BAN+{v!r}"
            else:
                parts.append(f"{k}={v!r}")
        lines.append("    dict(" + ", ".join(parts) + "),\n")
    lines.append("]\n\n")
    lines.append("assert len(SPECS) == 88, len(SPECS)\n")
    lines.append("for i, spec in enumerate(SPECS):\n")
    lines.append("    _l9(964 + i, **spec)\n")
    OUT.write_text("".join(lines), encoding="utf-8")
    print(f"wrote {OUT} specs={len(SPECS)}")


BAN_PLACEHOLDER = True

if __name__ == "__main__":
    main()
